<script>
(()=>{const services={{ \Illuminate\Support\Js::from($serviceOptions) }};const rows=document.querySelector('#items');const tpl=document.querySelector('#item-template');const type=document.querySelector('#discount-type');const money=n=>(Math.round((n+Number.EPSILON)*100)/100).toFixed(2);function suggest(r){const o=r.querySelector('.service').selectedOptions[0],service=services.find(x=>String(x.id)===o?.value),q=Number(r.querySelector('.qty').value)||1;if(service){const total=service.unit==='per_surface'?service.price+Math.max(0,q-1)*service.extra:service.price*q;r.querySelector('.price').value=money(total/q)}}function recalc(){let sub=0;rows.querySelectorAll('.item-row').forEach((r,i)=>{const q=Number(r.querySelector('.qty').value)||0,p=Number(r.querySelector('.price').value)||0;sub+=q*p;const s=r.querySelector('.service');s.name=`items[${i}][service_id]`;r.querySelector('.qty').name=`items[${i}][quantity]`;r.querySelector('.price').name=`items[${i}][unit_price_amount]`;r.querySelector('.tooth').name=`items[${i}][tooth_number]`});let d=0;if(type.value==='preset'){const o=document.querySelector('[name=discount_id]').selectedOptions[0];d=sub*(Number(o?.dataset.percent)||0)/100}else if(type.value==='custom_percent')d=sub*(Number(document.querySelector('#custom-value').value)||0)/100;else if(type.value==='custom_amount')d=Number(document.querySelector('#custom-value').value)||0;document.querySelector('#subtotal').textContent=money(sub);document.querySelector('#discount').textContent=money(d);document.querySelector('#total').textContent=money(Math.max(0,sub-d))}function add(){const n=tpl.content.cloneNode(true),r=n.querySelector('.item-row'),s=r.querySelector('.service');s.innerHTML='<option value="">Choose service</option>'+services.map(x=>`<option value="${x.id}" data-price="${x.price}">${x.name}</option>`).join('');s.addEventListener('change',()=>{suggest(r);recalc()});r.querySelector('.qty').addEventListener('input',()=>{suggest(r);recalc()});r.querySelector('.price').addEventListener('input',recalc);r.querySelector('.tooth').addEventListener('input',recalc);r.querySelector('.remove').addEventListener('click',()=>{r.remove();if(!rows.children.length)add();recalc()});rows.append(n);recalc()}document.querySelector('#add-item').addEventListener('click',add);type.addEventListener('change',()=>{const v=type.value;document.querySelector('#preset-wrap').hidden=v!=='preset';document.querySelector('#custom-wrap').hidden=!v.startsWith('custom_');document.querySelector('#reason-wrap').hidden=!v.startsWith('custom_');document.querySelector('[name=discount_id]').required=v==='preset';document.querySelector('#custom-value').required=v.startsWith('custom_');recalc()});document.querySelector('[name=discount_id]').addEventListener('change',recalc);document.querySelector('#custom-value').addEventListener('input',recalc);add()})();
</script>
